import pytest
from marshmallow.base import FieldABC, SchemaABC


class TestFieldABC:
    def test_cannot_instantiate(self):
        """FieldABC has abstract methods and cannot be instantiated."""
        with pytest.raises(TypeError):
            FieldABC()

    def test_incomplete_subclass_cannot_instantiate(self):
        """A subclass that doesn't implement all abstract methods cannot be instantiated."""
        class IncompleteField(FieldABC):
            pass

        with pytest.raises(TypeError):
            IncompleteField()

    def test_super_call_to_abstract_method(self):
        """Calling an abstract method via super() from a concrete subclass
        executes the method body (pass) instead of raising NotImplementedError."""
        class ConcreteField(FieldABC):
            def serialize(self, attr, obj, accessor=None):
                return super().serialize(attr, obj, accessor)
            def deserialize(self, value):
                return super().deserialize(value)
            def _serialize(self, value, attr, obj, **kwargs):
                return super()._serialize(value, attr, obj, **kwargs)
            def _deserialize(self, value, attr, data, **kwargs):
                return super()._deserialize(value, attr, data, **kwargs)

        field = ConcreteField()
        # These should not raise; at the parent they raise NotImplementedError
        assert field.serialize("attr", None) is None
        assert field.deserialize("value") is None
        assert field._serialize("value", "attr", None) is None
        assert field._deserialize("value", "attr", None) is None


class TestSchemaABC:
    def test_cannot_instantiate(self):
        """SchemaABC has abstract methods and cannot be instantiated."""
        with pytest.raises(TypeError):
            SchemaABC()

    def test_incomplete_subclass_cannot_instantiate(self):
        """A subclass that doesn't implement all abstract methods cannot be instantiated."""
        class IncompleteSchema(SchemaABC):
            pass

        with pytest.raises(TypeError):
            IncompleteSchema()

    def test_super_call_to_abstract_method(self):
        """Calling an abstract method via super() from a concrete subclass
        executes the method body (pass) instead of raising NotImplementedError."""
        class ConcreteSchema(SchemaABC):
            def dump(self, obj, *, many=None):
                return super().dump(obj, many=many)
            def dumps(self, obj, *, many=None):
                return super().dumps(obj, many=many)
            def load(self, data, *, many=None, partial=None, unknown=None):
                return super().load(data, many=many, partial=partial, unknown=unknown)
            def loads(self, json_data, *, many=None, partial=None, unknown=None, **kwargs):
                return super().loads(json_data, many=many, partial=partial, unknown=unknown, **kwargs)

        schema = ConcreteSchema()
        # These should not raise; at the parent they raise NotImplementedError
        assert schema.dump(None) is None
        assert schema.dumps(None) is None
        assert schema.load(None) is None
        assert schema.loads("") is None

